"% System Matrices
A_cl = [-0.55, 1.0; -3.9, -1.3];
B_cl = [0.0; 1.0];
C_cl = [1.0, 0.0];

% Simulation Parameters
dt = 0.01;
T = 30;
t = 0:dt:T;
N = length(t);

% Exact ZOH Discretization
I = eye(size(A_cl));
Ad = expm(A_cl * dt);
Bd = A_cl \ ((Ad - I) * B_cl);

% Simulation Loop
x = zeros(2, N);
y = zeros(1, N);
u = 1.0;

for k = 1:N-1
    x(:, k+1) = Ad * x(:, k) + Bd * u;
    y(k+1) = C_cl * x(:, k+1);
end

% Metrics Calculation
y_inf = -C_cl * (A_cl \ B_cl);
abs_y_inf = abs(y_inf);

% Rise Time (10%-90%)
y10 = 0.1 * y_inf;
y90 = 0.9 * y_inf;

idx10 = find(y(1:end-1) < y10 & y(2:end) >= y10, 1);
idx90 = find(y(1:end-1) < y90 & y(2:end) >= y90, 1);

if ~isempty(idx10)
    t10 = t(idx10) + dt * (y10 - y(idx10)) / (y(idx10+1) - y(idx10));
else
    t10 = 0;
end

if ~isempty(idx90)
    t90 = t(idx90) + dt * (y90 - y(idx90)) / (y(idx90+1) - y(idx90));
else
    t90 = 0;
end

rise_time_s = t90 - t10;

% Percent Overshoot
max_y = max(y);
overshoot_pct = (max_y - y_inf) / abs_y_inf * 100;

% Settling Time (Last sample > 2%)
tol = 0.02 * abs_y_inf;
outside_indices = find(abs(y - y_inf) > tol);

if ~isempty(outside_indices)
    settling_time_s = t(outside_indices(end));
else
    settling_time_s = 0;
end

% Write Result
result = struct( ...
    'rise_time_s', rise_time_s, ...
    'overshoot_pct', overshoot_pct, ...
    'settling_time_s', settling_time_s ...
);

fid = fopen('result.json', 'w');
fprintf(fid, '%s', jsonencode(result));
fclose(fid);"
